(()=>{'use strict';const form=document.querySelector('#quote-form');if(!form)return;form.hidden=false;
const tr=window.wavingTranslate||(s=>s),fr=document.documentElement.lang==='fr-CA';
const content=document.querySelector('#step-content'),prev=document.querySelector('#previous'),next=document.querySelector('#next'),error=document.querySelector('#form-error');
const projectFields=window.WAVING_QUOTE_FIELDS;
const needs=['Buy Flags','Custom Flags','Buy Flagpole','Flagpole Installation','Flag Rental','Flagpole Rental','Flagpole Repair','Flag Replacement','Commercial Flag Service','Multi-Location Program','Other'];
let step=0,busy=false,files=[],started=Date.now(),data={};const params=new URLSearchParams(location.search);if(needs.includes(params.get('need')))data.need=params.get('need');if(params.get('city'))data.city=params.get('city');if(params.get('topic'))data.topic=params.get('topic').slice(0,160);
Object.assign(data,projectFields.prefill(params));
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function event(name,extra={}){window.dispatchEvent(new CustomEvent('waving:analytics',{detail:{event:name,step:step+1,...extra}}));}form.addEventListener('input',()=>event('quote_start'),{once:true});
function field(name,label,type='text',required=false,options=[],hint=''){let control;if(type==='select')control=`<select id="q-${name}" name="${name}" ${required?'required':''}><option value="">${tr('Choose an option')}</option>${options.map(o=>`<option value="${e(o)}" ${data[name]===o?'selected':''}>${e(tr(o))}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea id="q-${name}" name="${name}" maxlength="4000" ${hint?`aria-describedby="q-${name}-hint"`:""} ${required?'required':''}>${e(data[name])}</textarea>`;else control=`<input id="q-${name}" name="${name}" type="${type}" value="${e(data[name])}" ${required?'required':''} ${type==='number'?'min="1" max="100000" step="1"':''} ${type==='text'?'maxlength="200"':''} ${name==='email'?'autocomplete="email"':name==='name'?'autocomplete="name"':name==='phone'?'autocomplete="tel"':name==='company'?'autocomplete="organization"':name==='postal'?'autocomplete="postal-code"':name==='city'?'autocomplete="address-level2"':''}>`;return `<label class="field" for="q-${name}"><span>${tr(label)}${required?' *':tr(' (optional)')}</span>${control}${hint?`<small id="q-${name}-hint">${tr(hint)}</small>`:''}</label>`}
function save(){content.querySelectorAll('input,select,textarea').forEach(el=>{if(el.type==='file')return;if(el.type==='radio'){if(el.checked)data[el.name]=el.value}else if(el.type==='checkbox')data[el.name]=el.checked;else data[el.name]=el.value.trim()})}
function showError(message,focus){error.textContent=tr(message).replace('{phone}',(window.WAVING_CONFIG||{}).phone||'(844) 834 - FLAG (3524)');error.hidden=false;if(focus){focus.setAttribute('aria-invalid','true');focus.setAttribute('aria-errormessage','form-error');focus.focus();}event('quote_validation_error')}
function valid(){save();error.hidden=true;content.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-errormessage')});for(const el of content.querySelectorAll('input,select,textarea')){if(el.type==='file')continue;if(el.name==='email')el.value=el.value.trim();if(el.name==='consent'&&!el.checked){showError('Please agree to be contacted about this request before sending.',el);return false}if((el.required&&typeof el.value==='string'&&!el.value.trim())||!el.checkValidity()){const label=el.closest('label')?.querySelector('span')?.textContent?.replace(' *','')||'this field';showError(el.validity.valueMissing?`Please complete ${label.toLowerCase()}.`:`Please check ${label.toLowerCase()}.`,el);return false}}const dateError=projectFields.dateError(data);if(dateError){showError(dateError,document.querySelector('#q-rentalEnd'));return false}return true}
function render(){
 error.hidden=true;prev.hidden=true;next.textContent=tr('REQUEST MY QUOTE');
 content.innerHTML='<h2>What do you need?</h2><p class="notice">Share what you know. Fields marked * are required.</p>'+
 (data.topic?'<p class="notice">'+tr('Project focus:')+' '+e(tr(data.topic))+'</p>':'')+
 field('need','Request','select',true,needs)+'<div id="project-fields"></div>'+
 field('notes','Anything else we should know?','textarea',false,[],'Choose a request type to see which details are useful. Share what you know; exact specifications can come later.')+
 '<details class="quote-attachments"><summary>Photos or artwork (optional)</summary><label class="field"><span>Choose files (optional)</span><input type="file" id="files" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.svg,.ai,.eps"><small>Up to 5 files. Maximum 10 MB per file and 20 MB total. JPG, PNG, WebP, PDF, SVG, AI or EPS. Do not include confidential documents.</small></label><ul id="file-list" class="file-list"></ul></details>'+
 '<h2 class="quote-contact-heading">How can we reach you?</h2><div class="form-grid">'+field('name','Name','text',true)+field('email','Email','email',true)+field('phone','Phone','tel')+field('city','City or community','text',true)+'</div>'+
 '<label class="consent"><input type="checkbox" name="consent" required><span>I agree to be contacted about this request and have read the <a href="/privacy/" target="_blank" rel="noopener">privacy information</a>. This is not marketing consent. *</span></label>';
 window.wavingLocalize?.(content);updateProjectFields();
 document.querySelector('#q-need').addEventListener('change',()=>{save();error.hidden=true;updateProjectFields();event('quote_request_changed',{requestType:data.need})});
 drawFiles();document.querySelector('#files').addEventListener('change',addFiles);event('quote_form_view');
}
function updateProjectFields(){
 const group=projectFields.groupForNeed(document.querySelector('#q-need').value),container=document.querySelector('#project-fields');
 container.innerHTML=group?'<fieldset class="quote-specific"><legend>'+e(tr(group.title))+'</legend><p class="notice">'+tr('Optional details — skip anything you do not know yet.')+'</p><div class="form-grid">'+group.fields.map(([name,label,type,options])=>field(name,label,type,false,options||[])).join('')+'</div></fieldset>':'';
 updateHint();
}
function updateHint(){
 const need=document.querySelector('#q-need').value;
 let hint='Choose a request type to see which details are useful. Share what you know; exact specifications can come later.';
 if(need==='Buy Flags'||need==='Flag Replacement')hint='Include flag types, approximate sizes and quantities, and your preferred delivery date.';
 else if(need==='Custom Flags')hint='Include quantities, sizes and your deadline. You can attach artwork below.';
 else if(need==='Buy Flagpole'||need==='Flagpole Installation')hint='Tell us the setting, approximate pole height and whether installation is needed. Photos are helpful.';
 else if(need==='Flag Rental'||need==='Flagpole Rental')hint='Include event dates, the venue, quantities and whether you need setup and collection.';
 else if(need==='Flagpole Repair')hint='Describe the issue and the existing pole. Ground-level photos can help us assess the request.';
 else if(need==='Commercial Flag Service'||need==='Multi-Location Program')hint='Include the number of sites, flagpoles and flags, plus the service or replacement schedule you have in mind.';
 document.querySelector('#q-notes-hint').textContent=tr(hint);
}
function drawFiles(){const list=document.querySelector('#file-list');list.replaceChildren();files.forEach((f,i)=>{const li=document.createElement('li');li.textContent=`${f.name} (${(f.size/1048576).toFixed(1)} ${fr?'Mo':'MB'}) `;const b=document.createElement('button');b.type='button';b.textContent=tr('REMOVE');b.setAttribute('aria-label',(fr?'Retirer ':'Remove ')+f.name);b.addEventListener('click',()=>{files.splice(i,1);drawFiles()});li.append(b);list.append(li)})}
function addFiles(ev){const selected=[...ev.target.files];let merged=[...files];for(const f of selected){if(!/\.(jpe?g|png|webp|pdf|svg|ai|eps)$/i.test(f.name)){showError('That file type is not supported. Choose an image, PDF or supported artwork file.');ev.target.value='';return}if(f.size>10*1048576){showError('Each file must be 10 MB or smaller.');ev.target.value='';return}if(!merged.some(x=>x.name===f.name&&x.size===f.size))merged.push(f)}if(merged.length>5||merged.reduce((a,f)=>a+f.size,0)>20*1048576){showError('Choose up to five files with a combined size of 20 MB or less.');ev.target.value='';return}files=merged;error.hidden=true;drawFiles();ev.target.value=''}
form.addEventListener('submit',async ev=>{ev.preventDefault();if(busy||!valid())return;await submit()});
async function submit(){const cfg=window.WAVING_CONFIG||{};if(!cfg.quoteEndpoint){showError('Your request could not be sent right now. Your entries are still here. Please call {phone} to discuss your quote.');event('quote_submit_unavailable');return}if(form.elements._gotcha.value||Date.now()-started<3000){showError('Please review your request and try again.');return}busy=true;next.disabled=true;prev.disabled=true;next.textContent=tr('SENDING…');form.setAttribute('aria-busy','true');const payload=new FormData();for(const [k,v]of Object.entries(window.WAVING_QUOTE_FIELDS.filterData(data)))if(v!==''&&v!==false)payload.append(k,String(v));files.forEach(f=>payload.append('attachment',f,f.name));payload.append('_subject','Waving.ca quote request — '+data.need);payload.append('_gotcha','');payload.append('language',document.documentElement.lang);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch(cfg.quoteEndpoint,{method:'POST',body:payload,headers:{Accept:'application/json'},signal:controller.signal});let result={};try{result=await r.json()}catch{throw new Error('Invalid response')}if(!r.ok||result.ok!==true||result.errors)throw new Error('Not accepted');form.hidden=true;const success=document.querySelector('#quote-success');success.hidden=false;success.setAttribute('tabindex','-1');success.focus();event('quote_submit_accepted')}catch(err){showError('We could not confirm that your request was accepted. Your entries are still here. Please try again later or call {phone}.');event('quote_submit_error')}finally{clearTimeout(timer);busy=false;next.disabled=false;prev.disabled=false;next.textContent=tr('REQUEST MY QUOTE');form.removeAttribute('aria-busy')}}
render();})();
